import { PlaceOrderCommand, PlaceOrderLineInput } from '../../application/dto/PlaceOrderCommand';
import { ValidationError } from '../../domain/errors/DomainErrors';
import { OrderStatus, isOrderStatus } from '../../domain/order/OrderStatus';

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function parseLine(value: unknown, index: number): PlaceOrderLineInput {
  if (!isRecord(value) || typeof value.productId !== 'string' || typeof value.quantity !== 'number') {
    throw new ValidationError(`lines[${index}] must have a string 'productId' and a numeric 'quantity'`);
  }
  return { productId: value.productId, quantity: value.quantity };
}

/** Checks the shape of an untrusted request body; business rules are enforced by the domain. */
export function parsePlaceOrderBody(body: unknown): PlaceOrderCommand {
  if (!isRecord(body)) {
    throw new ValidationError('Request body must be a JSON object');
  }
  if (typeof body.customerId !== 'string') {
    throw new ValidationError("'customerId' must be a string");
  }
  if (!Array.isArray(body.lines)) {
    throw new ValidationError("'lines' must be an array");
  }
  return { customerId: body.customerId, lines: body.lines.map(parseLine) };
}

export function parseStateQuery(value: unknown): OrderStatus | undefined {
  if (value === undefined) {
    return undefined;
  }
  if (typeof value !== 'string' || !isOrderStatus(value)) {
    throw new ValidationError(`Unknown order state '${String(value)}'`);
  }
  return value;
}

